base = pathlib.Path(r"C:\Users\bssho\Downloads\paperclip-master")
va = base / "video-automation"
print("=== video-automation tree ===")
for p in sorted(va.rglob("*")):
    print(" ", p.relative_to(va), f"({p.stat().st_size}B)" if p.is_file() else "/")

draft_root = pathlib.Path(r"C:\Users\bssho\AppData\Local\CapCut\User Data\Projects\com.lveditor.draft")
print("\n=== CapCut Drafts Summary ===")
root_meta_path = draft_root / "root_meta_info.json"
root_meta_map = {}
if root_meta_path.exists():
    rm = json.loads(root_meta_path.read_text(encoding="utf-8"))
    for entry in rm.get("all_draft_store", []):
        root_meta_map[entry.get("draft_name")] = {
            "cloud_dl": entry.get("draft_cloud_last_action_download"),
            "space_id": entry.get("tm_draft_cloud_space_id"),
            "new_version": entry.get("draft_new_version"),
            "duration": entry.get("tm_duration"),
        }

for d in sorted(draft_root.iterdir()):
    if not d.is_dir():
        continue
    dc = d / "draft_content.json"
    dm = d / "draft_meta_info.json"
    dvs = d / "draft_virtual_store.json"
    tl_dcs = list(d.glob("Timelines/*/draft_content.json"))

    dc_first = open(dc, "rb").read(1) if dc.exists() else None
    dm_first = open(dm, "rb").read(1) if dm.exists() else None
    tl_firsts = [open(p, "rb").read(1) for p in tl_dcs]

    app_ver = None
    new_ver = None
    dev_id = None
    if dc.exists() and dc_first == b"{":
        try:
            data = json.loads(dc.read_text(encoding="utf-8"))
            plat = data.get("last_modified_platform") or data.get("platform") or {}
            app_ver = plat.get("app_version")
            dev_id = plat.get("device_id")
            new_ver = data.get("new_version")
        except Exception as e:
            app_ver = f"err:{e}"
    print(f"- {d.name}: root_dc={dc_first}, dm={dm_first}, timelines={len(tl_dcs)} ({set(tl_firsts)}), app_ver={app_ver}, new_ver={new_ver}, in_root_meta={d.name in root_meta_map} {root_meta_map.get(d.name, '')}")
"}

