{"code":"import json, pathlib

draft_root = pathlib.Path(r"C:\Users\bssho\AppData\Local\CapCut\User Data\Projects\com.lveditor.draft")

# 1. Inspect pycapcut_smoke_A and pycapcut_smoke_B in detail
for sname in ["pycapcut_smoke_A", "pycapcut_smoke_B"]:
    sd = draft_root / sname
    print(f"=== {sname} files ===")
    for p in sorted(sd.rglob("*")):
        print(" ", p.relative_to(sd), p.stat().st_size, "mtime:", p.stat().st_mtime)
    dc = json.loads((sd / "draft_content.json").read_text(encoding="utf-8"))
    print("  id:", dc.get("id"), "name:", dc.get("name"), "version:", dc.get("version"), "new_version:", dc.get("new_version"))
    print("  platform:", dc.get("platform"))
    print("  last_modified_platform:", dc.get("last_modified_platform"))
    print("  texts:", dc.get("materials", {}).get("texts"))

# 2. Inspect encrypted vs partial-encrypted vs plaintext drafts in detail
for dname in ["57.08 벤츠 지바겐 광각 [26.04.13]", "롱폼 영상 프로젝트", "옵틱글래스 광각미러 템플릿 1", "전사스 템플릿3", "0729"]:
    d = draft_root / dname
    print(f"\n=== {dname} top-level files ===")
    for p in sorted(d.iterdir()):
        if p.is_file():
            first_b = open(p, "rb").read(16)
            is_json = first_b.startswith(b"{") or first_b.startswith(b"[")
            print(f"  {p.name}: {p.stat().st_size}B, json={is_json}, head={first_b[:10]!r}")
        else:
            print(f"  {p.name}/ ({len(list(p.rglob('*')))} items)")
    dvs = d / "draft_virtual_store.json"
    if dvs.exists() and open(dvs, "rb").read(1) == b"{":
        vdata = json.loads(dvs.read_text(encoding="utf-8"))
        enc_items = [x for x in vdata.get("draft_virtual_store", []) if isinstance(x, dict) and x.get("is_encrypted")]
        # Also search recursively for is_encrypted in vdata
        def find_enc(obj):
            found = []
            if isinstance(obj, dict):
                if obj.get("is_encrypted") is not None:
                    found.append(obj)
                for v in obj.values():
                    found.extend(find_enc(v))
            elif isinstance(obj, list):
                for item in obj:
                    found.extend(find_enc(item))
            return found
        encs = find_enc(vdata)
        print(f"  draft_virtual_store is_encrypted entries ({len(encs)}): {encs[:5]}")
"}

