{"content":"import json
import pathlib
import pycapcut as cc
from pycapcut.metadata import (
    TransitionType, FilterType, FontType,
    TextIntro, TextOutro, TextLoopAnim,
    IntroType, OutroType, GroupAnimationType,
    VideoSceneEffectType, VideoCharacterEffectType,
    AudioSceneEffectType, MaskType
)

base_dir = pathlib.Path(r"C:\Users\bssho\Downloads\paperclip-master\video-automation")
strategy_dir = base_dir / "strategy"
specs_dir = strategy_dir / "specs"
exp_dir = strategy_dir / "experiments"
for d in [strategy_dir, specs_dir, exp_dir]:
    d.mkdir(parents=True, exist_ok=True)

# 1. Write strategy/spec.schema.json
schema = {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "https://nousresearch.com/schemas/video-automation-spec-v0.1.json",
    "title": "Neutral Video Editing Spec v0.1",
    "description": "렌더러 중립 영상 편집 명세 (CapCut pyCapCut / FilmCraft headless 컴파일 공용)",
    "type": "object",
    "required": ["spec_version", "canvas", "styles", "scenes"],
    "properties": {
        "spec_version": {"type": "string", "const": "0.1"},
        "meta": {
            "type": "object",
            "properties": {
                "template_name": {"type": "string"},
                "source_type": {"type": "string", "enum": ["local_draft", "team_space_draft", "store_template", "markdown_brief"]},
                "duration_s": {"type": "number", "minimum": 0},
                "notes": {"type": "string"}
            }
        },
        "canvas": {
            "type": "object",
            "required": ["w", "h", "fps"],
            "properties": {
                "w": {"type": "integer", "minimum": 1},
                "h": {"type": "integer", "minimum": 1},
                "fps": {"type": "number", "minimum": 1},
                "aspect": {"type": "string"}
            }
        },
        "audio": {
            "type": "object",
            "properties": {
                "bgm_slot": {"type": ["string", "null"]},
                "bpm": {"type": ["number", "null"]},
                "downbeats_s": {"type": "array", "items": {"type": "number"}},
                "sections": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "required": ["label", "start", "end"],
                        "properties": {
                            "label": {"type": "string"},
                            "start": {"type": "number"},
                            "end": {"type": "number"}
                        }
                    }
                }
            }
        },
        "styles": {
            "type": "object",
            "additionalProperties": {
                "type": "object",
                "required": ["font", "size_pct", "color", "anchor"],
                "properties": {
                    "font": {"type": "string", "default": "Noto Sans KR"},
                    "weight": {"type": "integer", "default": 700},
                    "capcut_font": {
                        "type": ["object", "null"],
                        "properties": {
                            "resource_id": {"type": ["string", "null"]},
                            "enum_name": {"type": ["string", "null"]}
                        }
                    },
                    "size_pct": {"type": "number"},
                    "color": {"type": "string", "pattern": "^#[0-9A-Fa-f]{6}$"},
                    "stroke": {
                        "type": ["object", "null"],
                        "properties": {
                            "color": {"type": "string"},
                            "w": {"type": "number"}
                        }
                    },
                    "anchor": {
                        "type": "array",
                        "items": {"type": "number"},
                        "minItems": 2,
                        "maxItems": 2
                    }
                }
            }
        },
        "scenes": {
            "type": "array",
            "items": {
                "type": "object",
                "required": ["id", "start", "dur", "slot", "texts", "confidence", "needs_review"],
                "properties": {
                    "id": {"type": "string"},
                    "start": {"type": "number", "minimum": 0},
                    "dur": {"type": "number", "minimum": 0},
                    "snap": {"type": ["string", "null"]},
                    "slot": {
                        "type": "object",
                        "required": ["id", "kind", "aspect", "min_src_dur", "fit"],
                        "properties": {
                            "id": {"type": "string"},
                            "kind": {"type": "string", "enum": ["video", "photo", "gif"]},
                            "aspect": {"type": "string"},
                            "min_src_dur": {"type": "number"},
                            "subject_hint": {"type": "string"},
                            "fit": {"type": "string", "enum": ["cover", "contain", "fill"]}
                        }
                    },
                    "motion": {
                        "type": ["object", "null"],
                        "properties": {
                            "type": {"type": "string"},
                            "from": {"type": "number"},
                            "to": {"type": "number"},
                            "ease": {"type": "string"},
                            "capcut": {"type": ["object", "null"]}
                        }
                    },
                    "texts": {
                        "type": "array",
                        "items": {
                            "type": "object",
                            "required": ["text", "style", "t"],
                            "properties": {
                                "text": {"type": "string"},
                                "style": {"type": "string"},
                                "t": {
                                    "type": "array",
                                    "items": {"type": "number"},
                                    "minItems": 2,
                                    "maxItems": 2
                                },
                                "in": {"type": ["object", "null"]},
                                "out": {"type": ["object", "null"]},
                                "loop": {"type": ["object", "null"]},
                                "capcut_text_effect": {"type": ["object", "null"]}
                            }
                        }
                    },
                    "transition_out": {
                        "type": ["object", "null"],
                        "properties": {
                            "class": {"type": "string"},
                            "dur": {"type": "number"},
                            "capcut": {"type": ["object", "null"]},
                            "fallback": {"type": "string"}
                        }
                    },
                    "effects": {
                        "type": "array",
                        "items": {
                            "type": "object",
                            "properties": {
                                "class": {"type": "string"},
                                "at": {"type": "number"},
                                "dur": {"type": "number"},
                                "capcut": {"type": ["object", "null"]}
                            }
                        }
                    },
                    "audio_cue": {
                        "type": ["object", "null"],
                        "properties": {
                            "sfx": {"type": ["string", "null"]},
                            "tts_text": {"type": ["string", "null"]},
                            "at": {"type": "number"},
                            "dur": {"type": "number"},
                            "duck_db": {"type": "number"}
                        }
                    },
                    "confidence": {
                        "type": "object",
                        "properties": {
                            "timing": {"type": "number"},
                            "transition": {"type": "number"},
                            "text_style": {"type": "number"}
                        }
                    },
                    "needs_review": {
                        "type": "array",
                        "items": {"type": "string"}
                    }
                }
            }
        }
    }
}

(strategy_dir / "spec.schema.json").write_text(json.dumps(schema, ensure_ascii=False, indent=2), encoding="utf-8")
print("Wrote strategy/spec.schema.json")

# Index pyCapCut enums
enums = [
    ("TransitionType", TransitionType),
    ("FilterType", FilterType),
    ("FontType", FontType),
    ("TextIntro", TextIntro),
    ("TextOutro", TextOutro),
    ("TextLoopAnim", TextLoopAnim),
    ("IntroType", IntroType),
    ("OutroType", OutroType),
    ("GroupAnimationType", GroupAnimationType),
    ("VideoSceneEffectType", VideoSceneEffectType),
    ("VideoCharacterEffectType", VideoCharacterEffectType),
    ("AudioSceneEffectType", AudioSceneEffectType),
    ("MaskType", MaskType),
]
by_res_id = {}
for ename, ecls in enums:
    for member in ecls:
        val = member.value
        rid = getattr(val, "resource_id", None) or getattr(val, "effect_id", None)
        if rid:
            by_res_id[str(rid)] = {
                "enum": f"{ename}.{member.name}",
                "resource_id": str(rid),
                "is_vip": bool(getattr(val, "is_vip", False)),
                "title": getattr(val, "name", None) or getattr(val, "title", None) or member.name
            }

def rgb_to_hex(rgb):
    if not rgb or len(rgb) < 3:
        return "#FFFFFF"
    r, g, b = [max(0, min(255, int(round(c * 255)))) for c in rgb[:3]]
    return f"#{r:02X}{g:02X}{b:02X}"

def convert_draft_to_spec(draft_path: pathlib.Path, template_id: str, source_type: str):
    data = json.loads((draft_path / "draft_content.json").read_text(encoding="utf-8"))
    canvas = data.get("canvas_config", {})
    w = canvas.get("width", 1080)
    h = canvas.get("height", 1920)
    fps = float(data.get("fps", 30.0))
    dur_s = round((data.get("duration") or 0) / 1e6, 3)
    aspect = "9:16" if w < h else ("16:9" if w > h else "1:1")

    mats = data.get("materials", {})
    v_map = {m["id"]: m for m in mats.get("videos", [])}
    a_map = {m["id"]: m for m in mats.get("audios", [])}
    t_map = {m["id"]: m for m in mats.get("texts", [])}
    tr_map = {m["id"]: m for m in mats.get("transitions", [])}
    ve_map = {m["id"]: m for m in mats.get("video_effects", [])}
    ef_map = {m["id"]: m for m in mats.get("effects", [])}
    ma_map = {m["id"]: m for m in mats.get("material_animations", [])}

    # Collect video segments across video tracks and sort by target start time
    v_segs = []
    t_segs = []
    e_segs = []
    a_segs = []
    for tr in data.get("tracks", []):
        ttype = tr.get("type")
        for seg in tr.get("segments", []):
            if ttype == "video":
                v_segs.append(seg)
            elif ttype == "text":
                t_segs.append(seg)
            elif ttype == "effect":
                e_segs.append(seg)
            elif ttype == "audio":
                a_segs.append(seg)

    v_segs.sort(key=lambda s: (s.get("target_timerange", {}).get("start", 0), -s.get("target_timerange", {}).get("duration", 0)))
    t_segs.sort(key=lambda s: s.get("target_timerange", {}).get("start", 0))
    a_segs.sort(key=lambda s: s.get("target_timerange", {}).get("start", 0))

    styles = {
        "default_ko": {
            "font": "Noto Sans KR",
            "weight": 700,
            "capcut_font": {"resource_id": "7189852363404874242", "enum_name": None},
            "size_pct": 7.5,
            "color": "#FFFFFF",
            "stroke": {"color": "#000000", "w": 0.08},
            "anchor": [0.5, 0.78]
        }
    }

    scenes = []
    for idx, vs in enumerate(v_segs, 1):
        ttr = vs.get("target_timerange", {})
        start_s = round(ttr.get("start", 0) / 1e6, 3)
        seg_dur_s = round(ttr.get("duration", 0) / 1e6, 3)
        end_s = round(start_s + seg_dur_s, 3)
        vm = v_map.get(vs.get("material_id"), {})
        kind = vm.get("type", "video")
        if kind not in ("video", "photo", "gif"):
            kind = "video"
        src_name = pathlib.Path(vm.get("path", f"clip_{idx}")).stem

        needs_review = []
        # Check extra_material_refs on video segment for transitions, animations, effects
        trans_out = None
        motion = None
        seg_effects = []
        for ref_id in vs.get("extra_material_refs", []):
            if ref_id in tr_map:
                tr_m = tr_map[ref_id]
                rid = str(tr_m.get("effect_id") or tr_m.get("resource_id") or "")
                cc_match = by_res_id.get(rid)
                tr_dur = round((tr_m.get("duration") or 500000) / 1e6, 3)
                trans_out = {
                    "class": tr_m.get("name") or "transition",
                    "dur": tr_dur,
                    "capcut": cc_match if cc_match else {"resource_id": rid, "name": tr_m.get("name"), "unmatched": True},
                    "fallback": "dissolve"
                }
                if not cc_match or cc_match.get("is_vip") or tr_m.get("is_vip"):
                    needs_review.append(f"transition_out:{tr_m.get('name')}({rid})")
            elif ref_id in ma_map:
                anims = ma_map[ref_id].get("animations", [])
                for an in anims:
                    arid = str(an.get("resource_id") or an.get("id") or "")
                    cc_match = by_res_id.get(arid)
                    motion = {
                        "type": an.get("name") or an.get("type") or "anim",
                        "from": 1.0,
                        "to": 1.08,
                        "ease": "ease_out",
                        "capcut": cc_match if cc_match else {"resource_id": arid, "name": an.get("name"), "unmatched": True}
                    }
                    if not cc_match or cc_match.get("is_vip") or an.get("is_vip"):
                        needs_review.append(f"video_anim:{an.get('name')}({arid})")
            elif ref_id in ve_map:
                ve_m = ve_map[ref_id]
                rid = str(ve_m.get("resource_id") or ve_m.get("effect_id") or "")
                cc_match = by_res_id.get(rid)
                seg_effects.append({
                    "class": ve_m.get("name") or "video_effect",
                    "at": 0.0,
                    "dur": seg_dur_s,
                    "capcut": cc_match if cc_match else {"resource_id": rid, "name": ve_m.get("name"), "unmatched": True}
                })
                if not cc_match or cc_match.get("is_vip") or ve_m.get("is_vip"):
                    needs_review.append(f"video_effect:{ve_m.get('name')}({rid})")

        # Also check track-level effect segments overlapping this scene
        for es in e_segs:
            ettr = es.get("target_timerange", {})
            es_start = ettr.get("start", 0) / 1e6
            es_end = es_start + (ettr.get("duration", 0) / 1e6)
            if max(start_s, es_start) < min(end_s, es_end):
                ve_m = ve_map.get(es.get("material_id")) or ef_map.get(es.get("material_id")) or {}
                rid = str(ve_m.get("resource_id") or ve_m.get("effect_id") or "")
                cc_match = by_res_id.get(rid)
                seg_effects.append({
                    "class": ve_m.get("name") or "track_effect",
                    "at": round(max(0.0, es_start - start_s), 3),
                    "dur": round(min(end_s, es_end) - max(start_s, es_start), 3),
                    "capcut": cc_match if cc_match else {"resource_id": rid, "name": ve_m.get("name"), "unmatched": True}
                })
                if not cc_match or cc_match.get("is_vip") or ve_m.get("is_vip"):
                    needs_review.append(f"track_effect:{ve_m.get('name')}({rid})")

        # Find overlapping text segments (assign to scene if midpoint is within scene)
        scene_texts = []
        for ts in t_segs:
            tttr = ts.get("target_timerange", {})
            ts_start = tttr.get("start", 0) / 1e6
            ts_dur = tttr.get("duration", 0) / 1e6
            ts_mid = ts_start + ts_dur / 2.0
            if start_s <= ts_mid < end_s or (idx == len(v_segs) and ts_mid >= start_s):
                tm = t_map.get(ts.get("material_id"), {})
                try:
                    cobj = json.loads(tm.get("content", "{}"))
                except Exception:
                    cobj = {}
                txt_str = cobj.get("text", "").strip()
                st_list = cobj.get("styles", [{}])
                st0 = st_list[0] if st_list else {}
                fill_rgb = st0.get("fill", {}).get("content", {}).get("solid", {}).get("color", [1, 1, 1])
                hex_col = rgb_to_hex(fill_rgb)
                sz = float(st0.get("size", 12.0))
                clip_xy = ts.get("clip", {}).get("transform", {"x": 0.0, "y": -0.55})
                # Convert CapCut normalized [-1, 1] transform to [0, 1] anchor
                ax = round((float(clip_xy.get("x", 0.0)) + 1.0) / 2.0, 3)
                ay = round((1.0 - float(clip_xy.get("y", -0.55))) / 2.0, 3)
                style_key = f"style_s{idx:02d}_{len(scene_texts)+1}"
                styles[style_key] = {
                    "font": "Noto Sans KR",
                    "weight": 700,
                    "capcut_font": {"resource_id": "7189852363404874242", "enum_name": None},
                    "size_pct": round(sz / 2.0, 2),
                    "color": hex_col,
                    "stroke": {"color": "#000000", "w": 0.08},
                    "anchor": [ax, ay]
                }

                t_in = None
                t_out = None
                t_loop = None
                t_eff = None
                for ref_id in ts.get("extra_material_refs", []):
                    if ref_id in ma_map:
                        for an in ma_map[ref_id].get("animations", []):
                            atype = an.get("type")
                            arid = str(an.get("resource_id") or an.get("id") or "")
                            cc_match = by_res_id.get(arid)
                            a_obj = {
                                "class": an.get("name") or atype or "anim",
                                "dur": round((an.get("duration") or 300000) / 1e6, 3),
                                "capcut": cc_match if cc_match else {"resource_id": arid, "name": an.get("name"), "unmatched": True}
                            }
                            if atype == "in":
                                t_in = a_obj
                            elif atype == "out":
                                t_out = a_obj
                            else:
                                t_loop = a_obj
                            if not cc_match or cc_match.get("is_vip") or an.get("is_vip"):
                                needs_review.append(f"text_anim:{an.get('name')}({arid})")
                    elif ref_id in ef_map:
                        ef_m = ef_map[ref_id]
                        erid = str(ef_m.get("resource_id") or ef_m.get("effect_id") or "")
                        cc_match = by_res_id.get(erid)
                        t_eff = {
                            "name": ef_m.get("name"),
                            "resource_id": erid,
                            "capcut": cc_match
                        }
                        if not cc_match or ef_m.get("is_vip"):
                            needs_review.append(f"text_effect:{ef_m.get('name')}({erid})")

                rel_start = round(max(0.0, ts_start - start_s), 3)
                rel_end = round(min(seg_dur_s, (ts_start + ts_dur) - start_s), 3)
                scene_texts.append({
                    "text": txt_str,
                    "style": style_key,
                    "t": [rel_start, rel_end],
                    "in": t_in,
                    "out": t_out,
                    "loop": t_loop,
                    "capcut_text_effect": t_eff
                })

        # Overlapping audio cues (TTS or SFX)
        audio_cue = None
        for aus in a_segs:
            attr = aus.get("target_timerange", {})
            a_start = attr.get("start", 0) / 1e6
            a_dur = attr.get("duration", 0) / 1e6
            a_mid = a_start + a_dur / 2.0
            am = a_map.get(aus.get("material_id"), {})
            if am.get("type") in ("text_to_audio", "extract_music", "sound") and (start_s <= a_start < end_s or start_s <= a_mid < end_s):
                audio_cue = {
                    "sfx": am.get("name") if am.get("type") != "text_to_audio" else None,
                    "tts_text": am.get("name") if am.get("type") == "text_to_audio" else None,
                    "at": round(max(0.0, a_start - start_s), 3),
                    "dur": round(a_dur, 3),
                    "duck_db": -6.0
                }
                break

        scenes.append({
            "id": f"s{idx:02d}",
            "start": start_s,
            "dur": seg_dur_s,
            "snap": f"cut#{idx}",
            "slot": {
                "id": f"clip_{idx:02d}",
                "kind": kind,
                "aspect": aspect,
                "min_src_dur": seg_dur_s,
                "subject_hint": src_name,
                "fit": "cover"
            },
            "motion": motion,
            "texts": scene_texts,
            "transition_out": trans_out,
            "effects": seg_effects,
            "audio_cue": audio_cue,
            "confidence": {
                "timing": 0.99,
                "transition": 0.85 if (not trans_out or not trans_out["capcut"].get("unmatched")) else 0.5,
                "text_style": 0.75
            },
            "needs_review": sorted(set(needs_review))
        })

    spec_obj = {
        "spec_version": "0.1",
        "meta": {
            "template_name": template_id,
            "source_type": source_type,
            "duration_s": dur_s,
            "notes": "폰트는 Noto Sans KR 규칙(10장)을 적용하고, pyCapCut 미매칭·VIP 에셋은 needs_review로 분리함."
        },
        "canvas": {"w": w, "h": h, "fps": fps, "aspect": aspect},
        "audio": {
            "bgm_slot": "bgm_main",
            "bpm": None,
            "downbeats_s": [sc["start"] for sc in scenes],
            "sections": [{"label": "full", "start": 0.0, "end": dur_s}]
        },
        "styles": styles,
        "scenes": scenes
    }
    return spec_obj

draft_root = pathlib.Path(r"C:\Users\bssho\AppData\Local\CapCut\User Data\Projects\com.lveditor.draft")
