{"code":"import json, pathlib, subprocess

res = subprocess.run(["tasklist", "/FI", "IMAGENAME eq CapCut.exe", "/NH", "/FO", "CSV"], capture_output=True, text=True)
cc_count = res.stdout.lower().count("capcut.exe")
print("CapCut.exe process count:", cc_count)

draft_root = pathlib.Path(r"C:\Users\bssho\AppData\Local\CapCut\User Data\Projects\com.lveditor.draft")
for name in ["pycapcut_smoke_A", "pycapcut_smoke_B", "hermes_font_probe"]:
    d = draft_root / name
    print(f"\n=== {name} (exists={d.exists()}) ===")
    if not d.exists():
        continue
    for p in sorted(d.rglob("*")):
        if p.is_file():
            fb = open(p, "rb").read(16)
            print(f"  {p.relative_to(d)}: {p.stat().st_size}B, first_byte={fb[:1]!r}, head={fb[:10]!r}")
    for dc in [d / "draft_content.json", *d.glob("Timelines/*/draft_content.json")]:
        if dc.exists() and open(dc, "rb").read(1) == b"{":
            data = json.loads(dc.read_text(encoding="utf-8"))
            print(f"  [{dc.relative_to(d)}] platform={data.get('platform')}, last_mod={data.get('last_modified_platform')}, new_ver={data.get('new_version')}")
    dvs = d / "draft_virtual_store.json"
    if dvs.exists() and open(dvs, "rb").read(1) == b"{":
        vdata = json.loads(dvs.read_text(encoding="utf-8"))
        print(f"  [draft_virtual_store.json] {json.dumps(vdata, ensure_ascii=False)[:400]}")
"}

{"code":"import json, pathlib, subprocess

res = subprocess.run(["tasklist", "/FI", "IMAGENAME eq CapCut.exe", "/NH", "/FO", "CSV"], capture_output=True, text=True)
cc_count = res.stdout.lower().count("capcut.exe")
print("CapCut.exe process count:", cc_count)

draft_root = pathlib.Path(r"C:\Users\bssho\AppData\Local\CapCut\User Data\Projects\com.lveditor.draft")
# Check recently modified drafts in com.lveditor.draft
recent = sorted([d for d in draft_root.iterdir() if d.is_dir()], key=lambda p: p.stat().st_mtime, reverse=True)[:6]
for d in recent:
    print("Recent dir:", d.name, "mtime:", d.stat().st_mtime)
    for dc in [d / "draft_content.json", *d.glob("Timelines/*/draft_content.json")]:
        if dc.exists():
            fb = open(dc, "rb").read(1)
            print(" ", dc.relative_to(d), "first_byte:", fb, "size:", dc.stat().st_size)
            if fb == b"{":
                data = json.loads(dc.read_text(encoding="utf-8"))
                for tx in data.get("materials", {}).get("texts", []):
                    print("   text fonts:", tx.get("fonts"))
                    print("   text content:", tx.get("content"))

# Also search Cache/effect and Windows/Fonts for Condensed or Noto
for root_p in [
    pathlib.Path(r"C:\Users\bssho\AppData\Local\CapCut\User Data\Cache\effect"),
    pathlib.Path(r"C:\Users\bssho\AppData\Local\CapCut\Apps"),
    pathlib.Path(r"C:\Windows\Fonts"),
    pathlib.Path(r"C:\Users\bssho\AppData\Local\Microsoft\Windows\Fonts")
]:
    if root_p.exists():
        matches = [p for p in root_p.rglob("*") if p.is_file() and ("noto" in p.name.lower() or "condensed" in p.name.lower())]
        if matches:
            print(f"Font matches in {root_p}: {[str(m) for m in matches[:20]]}")
"}

