{"code":"import json, pathlib

fcproj = json.loads(pathlib.Path(r"C:\Users\bssho\Downloads\paperclip-master\video-automation\work\filmcraft_polestar4.fcproj").read_text(encoding="utf-8"))

def find_clip(obj, target_id=18):
    if isinstance(obj, dict):
        if obj.get("id") == target_id and "effects" in obj:
            return obj
        for v in obj.values():
            r = find_clip(v, target_id)
            if r:
                return r
    elif isinstance(obj, list):
        for item in obj:
            r = find_clip(item, target_id)
            if r:
                return r
    return None

c18 = find_clip(fcproj, 18)
print(json.dumps(c18, ensure_ascii=False, indent=2))
"}

